import{_ as a,o as t,c as o,ah as i}from"./chunks/framework.Sdx4l2LO.js";const p=JSON.parse('{"title":"Feature Proof","description":"Autonomous visual evidence that DINOForge features work","frontmatter":{"title":"Feature Proof","description":"Autonomous visual evidence that DINOForge features work","layout":"home"},"headers":[],"relativePath":"proof/index.md","filePath":"proof/index.md","lastUpdated":1774839561000}'),r={name:"proof/index.md"};function n(s,e,l,d,u,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="feature-proof" tabindex="-1">Feature Proof <a class="header-anchor" href="#feature-proof" aria-label="Permalink to &quot;Feature Proof&quot;">​</a></h1><p>Autonomous visual evidence that all DINOForge features work. This page is auto-generated by <code>/prove-all</code> and updated per-commit with the latest evidence bundle.</p><h2 id="latest-run" tabindex="-1">Latest Run <a class="header-anchor" href="#latest-run" aria-label="Permalink to &quot;Latest Run&quot;">​</a></h2><p><strong>Status</strong>: Evidence bundles generated by the <code>/prove-all</code> command appear here.</p><p>Pipeline Version: Latest</p><hr><h2 id="validation-results" tabindex="-1">Validation Results <a class="header-anchor" href="#validation-results" aria-label="Permalink to &quot;Validation Results&quot;">​</a></h2><p>The feature proof pipeline validates three core DINOForge features:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Status</th></tr></thead><tbody><tr><td>Mods Button</td><td>Verified via VLM analysis</td></tr><tr><td>F9 Debug Overlay</td><td>Verified via VLM analysis</td></tr><tr><td>F10 Mod Menu</td><td>Verified via VLM analysis</td></tr></tbody></table><hr><h2 id="features-demonstrated" tabindex="-1">Features Demonstrated <a class="header-anchor" href="#features-demonstrated" aria-label="Permalink to &quot;Features Demonstrated&quot;">​</a></h2><h3 id="_1-mods-button-main-menu" tabindex="-1">1. Mods Button (Main Menu) <a class="header-anchor" href="#_1-mods-button-main-menu" aria-label="Permalink to &quot;1. Mods Button (Main Menu)&quot;">​</a></h3><p>The mod loading system is functional and displays the Mods button on the main menu screen.</p><h3 id="_2-f9-debug-overlay" tabindex="-1">2. F9 Debug Overlay <a class="header-anchor" href="#_2-f9-debug-overlay" aria-label="Permalink to &quot;2. F9 Debug Overlay&quot;">​</a></h3><p>In-game debug information display showing runtime statistics and entity counts.</p><h3 id="_3-f10-mod-menu" tabindex="-1">3. F10 Mod Menu <a class="header-anchor" href="#_3-f10-mod-menu" aria-label="Permalink to &quot;3. F10 Mod Menu&quot;">​</a></h3><p>The mod configuration menu with hotkey access to all loaded packs and settings.</p><hr><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p>The evidence in this directory is produced by the <code>/prove-all</code> command, which runs an autonomous pipeline:</p><ol><li><strong>Game Capture (Phase 1)</strong> — Records raw video clips of three core features with VLM (computer vision) validation</li><li><strong>Neural TTS (Phase 2)</strong> — Generates narration using Microsoft Edge&#39;s neural voice (edge-tts)</li><li><strong>Remotion Composition (Phase 3)</strong> — Renders videos with spring-physics callout boxes and audio</li><li><strong>Desktop Companion (Phase 4)</strong> — Records UI flow video (if Playwright tests configured)</li><li><strong>CLI Recordings (Phase 5)</strong> — Captures terminal sessions showing CLI tool usage (if VHS installed)</li><li><strong>Bundling (Phase 6-8)</strong> — Packages all artifacts to <code>docs/proof-of-features/</code> directory</li></ol><h3 id="technical-details" tabindex="-1">Technical Details <a class="header-anchor" href="#technical-details" aria-label="Permalink to &quot;Technical Details&quot;">​</a></h3><ul><li><strong>Window Capture</strong>: GDI title-based capture (title=&quot;Diplomacy is Not an Option&quot;)</li><li><strong>Key Injection</strong>: Win32 SendInput (no window focus required)</li><li><strong>VLM Validation</strong>: claude-haiku-4-5-20251001 analyzing live GDI screenshots</li><li><strong>TTS</strong>: edge-tts en-US-AriaNeural (free neural voice)</li><li><strong>Rendering</strong>: Remotion v4 with FFmpeg output</li></ul><hr><h2 id="raw-evidence-archives" tabindex="-1">Raw Evidence Archives <a class="header-anchor" href="#raw-evidence-archives" aria-label="Permalink to &quot;Raw Evidence Archives&quot;">​</a></h2><p>Evidence bundles are archived in <code>docs/proof-of-features/</code> with timestamped directories:</p><ul><li><code>docs/proof-of-features/dinoforge_proof_YYYYMMDD_HHMMSS/</code> — Full bundle with raw clips, screenshots, and rendered videos</li><li>Each bundle includes: <ul><li>Raw game clips (MP4)</li><li>VLM validation screenshots (PNG)</li><li>Rendered feature videos (MP4)</li><li>Validation report (JSON)</li><li>Human-readable summary (MD)</li></ul></li></ul><hr><h2 id="running-your-own" tabindex="-1">Running Your Own <a class="header-anchor" href="#running-your-own" aria-label="Permalink to &quot;Running Your Own&quot;">​</a></h2><p>To generate fresh proof:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/prove-all</span></span></code></pre></div><p>This command requires:</p><ul><li>Game installed at <code>G:\\SteamLibrary\\steamapps\\common\\Diplomacy is Not an Option\\</code></li><li>DINOForge DLL deployed and loading (F10 menu works, no error overlays)</li><li>Python 3 + edge-tts: <code>pip install edge-tts</code></li><li>Node.js 18+ with Remotion: <code>cd scripts/video &amp;&amp; npm install</code></li><li>ffmpeg: <code>C:\\program files\\imagemagick-7.1.0-q16-hdri\\ffmpeg.exe</code></li></ul><p>The entire pipeline takes ~10-15 minutes depending on Remotion render times.</p>',34)])])}const m=a(r,[["render",n]]);export{p as __pageData,m as default};
